#!/usr/bin/env bash
set -e
cd "$(dirname "$0")"
FF=./ffmpeg
mkdir -p reels_v2
$FF -y -f lavfi -i color=c=black:s=1080x1920:r=30:d=9.60 -loop 1 -framerate 30 -t 9.60 -i plates_v2/shaft.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/dustA.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/dustB.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/moonA.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/moonB.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/clock_a.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/label1.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/title5_blur.png -loop 1 -framerate 30 -t 9.60 -i plates_v2/title5.png -/filter_complex graph_b1.txt -map '[vf]' -t 9.40 -q:v 2 -start_number 0 -f image2 reels_v2/b1_%05d.jpg
$FF -y -f lavfi -i color=c=black:s=1080x1920:r=30:d=13.80 -loop 1 -framerate 30 -t 13.80 -i plates_v2/chatlabel.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/chatbar.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/dots_0.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/dots_1.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/dots_2.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/answertext.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/cover.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/chip_0.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/chip_1.png -loop 1 -framerate 30 -t 13.80 -i plates_v2/chip_2.png -/filter_complex graph_b2.txt -map '[vf]' -t 13.60 -q:v 2 -start_number 0 -f image2 reels_v2/b2_%05d.jpg
$FF -y -f lavfi -i color=c=black:s=1080x1920:r=30:d=16.80 -loop 1 -framerate 30 -t 16.80 -i plates_v2/floorgrad.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/bigT1.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/bigT2.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/floorword.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/floorlabel.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/cardA.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/cardB.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/cardC.png -loop 1 -framerate 30 -t 16.80 -i plates_v2/ribbon.png -/filter_complex graph_b3.txt -map '[vf]' -t 16.60 -q:v 2 -start_number 0 -f image2 reels_v2/b3_%05d.jpg
$FF -y -f lavfi -i color=c=black:s=1080x1920:r=30:d=12.90 -loop 1 -framerate 30 -t 12.90 -i plates_v2/wall_full.png -loop 1 -framerate 30 -t 12.90 -i plates_v2/dustA.png -loop 1 -framerate 30 -t 12.90 -i plates_v2/label4.png -loop 1 -framerate 30 -t 12.90 -i plates_v2/title3_blur.png -loop 1 -framerate 30 -t 12.90 -i plates_v2/title3.png -/filter_complex graph_b4.txt -map '[vf]' -t 12.70 -q:v 2 -start_number 0 -f image2 reels_v2/b4_%05d.jpg
$FF -y -f lavfi -i color=c=black:s=1080x1920:r=30:d=10.60 -loop 1 -framerate 30 -t 10.60 -i plates_v2/collage.png -loop 1 -framerate 30 -t 10.60 -i plates_v2/redlabel.png -loop 1 -framerate 30 -t 10.60 -i plates_v2/red4.png -loop 1 -framerate 30 -t 10.60 -i plates_v2/cta.png -loop 1 -framerate 30 -t 10.60 -i plates_v2/tear.png -/filter_complex graph_b5.txt -map '[vf]' -t 10.40 -q:v 2 -start_number 0 -f image2 reels_v2/b5_%05d.jpg
